import SwiftUI

enum ClientClay {
    // Explicit dark compatibility API. Adopt ClientClay.color(.semanticRole)
    // within a screen's approved migration; changing these globally is unsafe.
    static let canvas = ClientColorRole.backgroundPrimary.color(for: .dark)
    static let canvasWarm = ClientColorRole.backgroundSecondary.color(for: .dark)
    static let surface = ClientColorRole.surfacePrimary.color(for: .dark)
    static let surfaceDeep = ClientColorRole.surfaceSecondary.color(for: .dark)
    static let surfaceElevated = ClientColorRole.surfaceElevated.color(for: .dark)
    static let inset = ClientColorRole.surfaceInteractive.color(for: .dark)
    static let ink = ClientColorRole.textPrimary.color(for: .dark)
    static let inkSoft = ClientColorRole.textEmphasis.color(for: .dark)
    static let secondaryInk = ClientColorRole.textSecondary.color(for: .dark)
    static let tertiaryInk = ClientColorRole.textDisabled.color(for: .dark)
    static let accent = ClientColorRole.brandAccent.color(for: .dark)
    static let accentHot = ClientColorRole.brandAccentPressed.color(for: .dark)
    static let accentSoft = ClientColorRole.brandAccentSoft.color(for: .dark)
    static let sage = ClientColorRole.success.color(for: .dark)
    static let sageSoft = ClientColorRole.successMuted.color(for: .dark)
    static let runAccent = ClientColorRole.runningAccent.color(for: .dark)
    static let gold = ClientColorRole.warning.color(for: .dark)
    static let warning = ClientColorRole.warning.color(for: .dark)
    static let border = ClientColorRole.textInverse.color(for: .dark).opacity(0.08)
    static let radius = ClientRadius.card
    static let pagePadding = ClientSpacing.page

    static let brandGradient = LinearGradient(
        colors: [accent, accentHot],
        startPoint: .topLeading,
        endPoint: .bottomTrailing
    )
}

enum ClientSurfaceAppearance: Equatable { case legacyDark, adaptive }

struct ClayCardModifier: ViewModifier {
    var padding: CGFloat = ClientSpacing.legacyCardInset
    var appearance: ClientSurfaceAppearance = .legacyDark
    @Environment(\.colorSchemeContrast) private var contrast
    @Environment(\.colorScheme) private var colorScheme

    private func color(_ role: ClientColorRole) -> Color {
        appearance == .adaptive ? ClientClay.color(role) : role.color(for: .dark)
    }

    func body(content: Content) -> some View {
        let elevation = appearance == .legacyDark ? ClientElevation.legacyCard
            : colorScheme == .dark ? ClientElevation.darkSurface : ClientElevation.lightSurface
        return content
            .padding(padding)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background {
                RoundedRectangle(cornerRadius: ClientClay.radius, style: .continuous)
                    .fill(LinearGradient(colors: [color(.surfaceSecondary), color(.surfacePrimary)], startPoint: .topLeading, endPoint: .bottomTrailing))
                    .shadow(color: ClientClay.shadow.opacity(elevation.opacity), radius: elevation.radius, y: elevation.y)
                    .overlay {
                        RoundedRectangle(cornerRadius: ClientClay.radius, style: .continuous)
                            .stroke(appearance == .adaptive ? ClientClay.color(contrast == .increased ? .borderStrong : .borderSubtle)
                                    : ClientClay.onDark.opacity(contrast == .increased ? 0.22 : 0.08),
                                    lineWidth: contrast == .increased ? ClientBorder.emphasized : ClientBorder.subtle)
                    }
            }
    }
}

struct ClientPremiumCardModifier: ViewModifier {
    var tint: Color = ClientClay.accent
    var padding: CGFloat = ClientSpacing.group

    func body(content: Content) -> some View {
        content
