    @EnvironmentObject private var healthKit: HealthKitStepService
    @EnvironmentObject private var avatarStore: ClientAvatarStore
    @Environment(\.scenePhase) private var scenePhase
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var presentedWorkout: ClientWorkoutSession?

    private var activeWorkoutPlan: ClientWorkoutPlan? {
        if let assigned = snapshot.workout, assigned.isEffective() { return assigned }
        return identity.mode == .standalone ? session.personalContent.activeWorkout?.asClientPlan() : nil
    }

    private var activeNutritionPlan: ClientNutritionPlan? {
        if let assigned = snapshot.nutrition, assigned.isEffective() { return assigned }
        return identity.mode == .standalone ? session.personalContent.activeNutrition?.asClientPlan() : nil
    }

    private var todayWorkout: ClientWorkoutSession? {
        guard let plan = activeWorkoutPlan else { return nil }
        if let id = plan.todaySessionID { return plan.sessions.first { $0.id == id } }
        return identity.mode == .standalone ? plan.sessions.first : nil
    }

    private var todayNutrition: ClientNutritionDay? {
        activeNutritionPlan?.days.first { $0.weekday == ClientDateLogic.weekday(for: Date()) }
            ?? (activeNutritionPlan?.days.count == 1 ? activeNutritionPlan?.days.first : nil)
    }

    private var homeAgendaTasks: [PersonalAgendaTask] {
        session.agenda
            .filter { task in
                guard let date = task.date else { return true }
                return Calendar.current.isDateInToday(date)
            }
            .sorted {
                if $0.isCompleted != $1.isCompleted { return !$0.isCompleted }
                return ($0.date ?? .distantFuture) < ($1.date ?? .distantFuture)
            }
    }

    private var todayWorkoutExecution: ClientWorkoutExecution? {
        guard let todayWorkout else { return nil }
        return session.workoutExecution(sessionID: todayWorkout.id)
    }

    private var todayMealProgress: (completed: Int, total: Int) {
        guard let todayNutrition else { return (0, 0) }
