                    } label: {
                        VStack(alignment: .leading) {
                            Text(template.name)
                            Text("\(template.meal.foods.count) alimenti · \(Int(template.meal.calories.rounded())) kcal")
                                .font(.caption).foregroundStyle(.secondary)
                        }
                    }
