        camera = ClientRunningMap.camera(for: result.route)
        guard !reduceMotion, result.route.count > 1 else {
            visiblePointCount = result.route.count
            showSummary()
            return
        }
        let frameCount = min(result.route.count, 100)
        for frame in 1...frameCount {
